file.content:
:root {
  --text: #6b6375;
  --text-h: #08060d;
  --bg: #fff;
  --border: #e5e4e7;
  --code-bg: #f4f3ec;
  --accent: #aa3bff;
  --accent-bg: rgba(170, 59, 255, 0.1);
  --accent-border: rgba(170, 59, 255, 0.5);
  --social-bg: rgba(244, 243, 236, 0.5);
  --shadow:
    rgba(0, 0, 0, 0.1) 0 10px 15px -3px, rgba(0, 0, 0, 0.05) 0 4px 6px -2px;

  --sans: system-ui, 'Segoe UI', Roboto, sans-serif;
  --heading: system-ui, 'Segoe UI', Roboto, sans-serif;
  --mono: ui-monospace, Consolas, monospace;

  font: 18px/145% var(--sans);
  letter-spacing: 0.18px;
  color-scheme: light dark;
  color: var(--text);
  background: var(--bg);
  font-synthesis: none;
  text-rendering: optimizeLegibility;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;

  @media (max-width: 1024px) {
    font-size: 16px;
  }
}

@media (prefers-color-scheme: dark) {
  :root {
    --text: #9ca3af;
    --text-h: #f3f4f6;
    --bg: #16171d;
    --border: #2e303a;
    --code-bg: #1f2028;
    --accent: #c084fc;
    --accent-bg: rgba(192, 132, 252, 0.15);
    --accent-border: rgba(192, 132, 252, 0.5);
    --social-bg: rgba(47, 48, 58, 0.5);
    --shadow:
      rgba(0, 0, 0, 0.4) 0 10px 15px -3px, rgba(0, 0, 0, 0.25) 0 4px 6px -2px;
  }

  #social .button-icon {
    filter: invert(1) brightness(2);
  }
}

#root {
  width: 1126px;
  max-width: 100%;
  margin: 0 auto;
  text-align: center;
  border-inline: 1px solid var(--border);
  min-height: 100svh;
  display: flex;
  flex-direction: column;
  box-sizing: border-box;
}

body {
  margin: 0;
}

h1,
h2 {
  font-family: var(--heading);
  font-weight: 500;
  color: var(--text-h);
}

h1 {
  font-size: 56px;
  letter-spacing: -1.68px;
  margin: 32px 0;
  @media (max-width: 1024px) {
    font-size: 36px;
    margin: 20px 0;
  }
}
h2 {
  font-size: 24px;
  line-height: 118%;
  letter-spacing: -0.24px;
  margin: 0 0 8px;
  @media (max-width: 1024px) {
    font-size: 20px;
  }
}
p {
  margin: 0;
}

code,
.counter {
  font-family: var(--mono);
  display: inline-flex;
  border-radius: 4px;
  color: var(--text-h);
}

code {
  font-size: 15px;
  line-height: 135%;
  padding: 4px 8px;
  background: var(--code-bg);
}

input.content:
@import 'tailwindcss';

@custom-variant dark (&:where(.dark, .dark *));

@theme {
  --font-sans: 'Google Sans Text', 'Google Sans', 'Segoe UI', Roboto, Helvetica,
    Arial, system-ui, sans-serif;
  --font-display: 'Google Sans', 'Segoe UI', Roboto, Helvetica, Arial,
    system-ui, sans-serif;

  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-surface: var(--surface);
  --color-surface-hover: var(--surface-hover);
  --color-sidebar: var(--sidebar);
  --color-sidebar-hover: var(--sidebar-hover);
  --color-sidebar-active: var(--sidebar-active);
  --color-sidebar-active-fg: var(--sidebar-active-fg);
  --color-border: var(--border);
  --color-border-strong: var(--border-strong);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-unread: var(--unread);
  --color-star: var(--star);
  --color-danger: var(--danger);
  --color-success: var(--success);
  --color-warning: var(--warning);
  --color-ring: var(--ring);
  --color-card: var(--card);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);

  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
  --radius-xl: 24px;
  --radius-full: 999px;
}

:root {
  --background: #ffffff;
  --foreground: #1f1f1f;
  --surface: #ffffff;
  --surface-hover: #f2f2f2;
  --sidebar: #f6f8fc;
  --sidebar-hover: #e8eaed;
  --sidebar-active: #d3e3fd;
  --sidebar-active-fg: #001d35;
  --border: #e6e6e6;
  --border-strong: #dadce0;
  --muted: #f1f3f4;
  --muted-foreground: #5f6368;
  --accent: #0b57d0;
  --accent-foreground: #ffffff;
  --unread: #202124;
  --star: #f2b400;
  --danger: #d93025;
  --success: #1e8e3e;
  --warning: #f9ab00;
  --ring: #0b57d0;
  --card: #ffffff;
  --popover: #ffffff;
  --popover-foreground: #1f1f1f;
}

.dark {
  --background: #131314;
  --foreground: #e8eaed;
  --surface: #1e1f20;
  --surface-hover: #2a2b2d;
  --sidebar: #1b1c1d;
  --sidebar-hover: #2a2b2d;
  --sidebar-active: #37383a;
  --sidebar-active-fg: #d3e3fd;
  --border: #3c4043;
  --border-strong: #5f6368;
  --muted: #28292a;
  --muted-foreground: #9aa0a6;
  --accent: #a8c7fa;
  --accent-foreground: #062e6f;
  --unread: #e8eaed;
  --star: #f2b400;
  --danger: #f28b82;
  --success: #81c995;
  --warning: #fdd663;
  --ring: #a8c7fa;
  --card: #1e1f20;
  --popover: #282a2c;
  --popover-foreground: #e8eaed;
}

@layer base {
  * {
    border-color: var(--color-border);
  }

  html,
  body,
  #root {
    height: 100%;
  }

  body {
    margin: 0;
    background: var(--color-background);
    color: var(--color-foreground);
    font-family: var(--font-sans);
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
    overflow: hidden;
  }

  ::selection {
    background: var(--sidebar-active);
  }

  ::-webkit-scrollbar {
    width: 10px;
    height: 10px;
  }
  ::-webkit-scrollbar-track {
    background: transparent;
  }
  ::-webkit-scrollbar-thumb {
    background: color-mix(in srgb, var(--muted-foreground) 35%, transparent);
    border-radius: 999px;
    border: 2px solid transparent;
    background-clip: content-box;
  }
  ::-webkit-scrollbar-thumb:hover {
    background: color-mix(in srgb, var(--muted-foreground) 55%, transparent);
    background-clip: content-box;
  }
}

@layer utilities {
  .scrollbar-none {
    scrollbar-width: none;
  }
  .scrollbar-none::-webkit-scrollbar {
    display: none;
  }
}

