    }
    return {
      threads: [
        ...state.threads,
        {
          id: draftMessage.threadId,
          subject: win.subject || '(no subject)',
          messages: [draftMessage],
          labelIds: ['draft'],
          isImportant: false,
          snoozedUntil: null,
          scheduledFor: null,
