                key={thread.id}
                thread={thread}
                selected={selectedIds.includes(thread.id)}
                onToggleSelect={() => toggleSelected(thread.id)}
                onOpen={() => handleOpen(thread.id)}
              />
            ))}
          </div>
        </ScrollArea>
      )}
    </div>
  )
}

