      if (pendingG.current) {
        pendingG.current = false
        if (pendingTimer.current) window.clearTimeout(pendingTimer.current)
        const map: Record<string, { kind: 'folder'; id: 'inbox' | 'starred' | 'sent' | 'draft' | 'trash' }> = {
          i: { kind: 'folder', id: 'inbox' },
