      const targetIds = selectedThreadId ? [selectedThreadId] : selectedIds

      switch (e.key.toLowerCase()) {
        case 'g':
          pendingG.current = true
          pendingTimer.current = window.setTimeout(() => {
            pendingG.current = false
          }, 900)
          break
        case 'c':
          e.preventDefault()
          openCompose('new')
          break
        case 'e':
          if (targetIds.length) {
            e.preventDefault()
            archiveThreads(targetIds)
          }
          break
        case '#':
          if (targetIds.length) {
