  --color-sidebar-active: var(--sidebar-active);
  --color-sidebar-active-fg: var(--sidebar-active-fg);
  --color-border: var(--border);
  --color-border-strong: var(--border-strong);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-unread: var(--unread);
  --color-star: var(--star);
  --color-danger: var(--danger);
  --color-success: var(--success);
  --color-warning: var(--warning);
  --color-ring: var(--ring);
  --color-card: var(--card);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);

  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
  --radius-xl: 24px;
  --radius-full: 999px;
}

:root {
  --background: #ffffff;
  --foreground: #1f1f1f;
  --surface: #ffffff;
  --surface-hover: #f2f2f2;
  --sidebar: #f6f8fc;
  --sidebar-hover: #e8eaed;
  --sidebar-active: #d3e3fd;
  --sidebar-active-fg: #001d35;
  --border: #e6e6e6;
  --border-strong: #dadce0;
  --muted: #f1f3f4;
  --muted-foreground: #5f6368;
  --accent: #0b57d0;
  --accent-foreground: #ffffff;
  --unread: #202124;
  --star: #f2b400;
  --danger: #d93025;
  --success: #1e8e3e;
  --warning: #f9ab00;
  --ring: #0b57d0;
  --card: #ffffff;
  --popover: #ffffff;
  --popover-foreground: #1f1f1f;
}

.dark {
  --background: #131314;
  --foreground: #e8eaed;
  --surface: #1e1f20;
  --surface-hover: #2a2b2d;
  --sidebar: #1b1c1d;
  --sidebar-hover: #2a2b2d;
  --sidebar-active: #37383a;
  --sidebar-active-fg: #d3e3fd;
  --border: #3c4043;
  --border-strong: #5f6368;
  --muted: #28292a;
  --muted-foreground: #9aa0a6;
  --accent: #a8c7fa;
  --accent-foreground: #062e6f;
  --unread: #e8eaed;
  --star: #f2b400;
  --danger: #f28b82;
  --success: #81c995;
  --warning: #fdd663;
  --ring: #a8c7fa;
  --card: #1e1f20;
  --popover: #282a2c;
  --popover-foreground: #e8eaed;
}

@layer base {
  * {
    border-color: var(--color-border);
  }

  html,
  body,
  #root {
    height: 100%;
  }

  body {
    margin: 0;
    background: var(--color-background);
    color: var(--color-foreground);
    font-family: var(--font-sans);
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
    overflow: hidden;
  }

  ::selection {
    background: var(--sidebar-active);
  }

  ::-webkit-scrollbar {
    width: 10px;
    height: 10px;
  }
  ::-webkit-scrollbar-track {
    background: transparent;
  }
  ::-webkit-scrollbar-thumb {
    background: color-mix(in srgb, var(--muted-foreground) 35%, transparent);
    border-radius: 999px;
    border: 2px solid transparent;
    background-clip: content-box;
  }
  ::-webkit-scrollbar-thumb:hover {
    background: color-mix(in srgb, var(--muted-foreground) 55%, transparent);
    background-clip: content-box;
  }
}

@layer utilities {
  .scrollbar-none {
    scrollbar-width: none;
  }
  .scrollbar-none::-webkit-scrollbar {
    display: none;
  }
}

